import math


def fib(n: int):
    if n <= 0:
        raise ValueError("Input must be a non-negative integer.")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        # Using the closed-form expression of the Fibonacci number
        # based on the golden ratio: phi = (1 + sqrt(5)) / 2
        # F(n) = phi^n + (1 - phi)^n / sqrt(5)
        phi = (1 + math.sqrt(5)) / 2
        # Adjusted to Python's precision and rounding
        fib_n = round((phi**n - (1 - phi)**n) / math.sqrt(5))
        return fib_n


# Example usage (printing the first 10 Fibonacci numbers for demonstration):

if __name__ == "__main__":
    for i in range(1, 11):
        print(fib(i))
