import re


def valid_date(date):
    """Validates a date string and returns True if valid, False otherwise.

    Parameters:
        date (str): The date string to validate in the format mm-dd-yyyy.

    Returns:
        bool: True if the date string is valid, False otherwise.
    """

    # Check if the date string is empty
    if not date:
        return False

    # Check date format
    if not re.match(r'\d{2}-\d{2}-\d{4}$', date):
        return False

    # Split date into month, day, and year
    month, day, year = date.split('-')

    # Convert strings to integers
    month, day, year = map(int, [month, day, year])

    # Validate month and day
    if not (1 <= month <= 12):
        return False

    if month in [1, 3, 5, 7, 8, 10, 12]:
        if not (1 <= day <= 31):
            return False
    elif month in [4, 6, 9, 11]:
        if not (1 <= day <= 30):
            return False
    elif month == 2:
        if year % 4 == 0:
            if not (1 <= day <= 29):
                return False
        else:
            if not (1 <= day <= 28):
                return False
    else:
        # Leave this else statement as fallback for handling invalid month or year
        return False

    # If all conditions are passed, the date is valid
    return True

